package apextest

import (
	"encoding/json"
	"path/filepath"
	"testing"
)

// Original source and metadata of the exact Salesforce-admitted contract.
func TestRunJSONGeneratorPrettyContracts(t *testing.T) {
	root := t.TempDir()
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeJsonPrettyEdges67.cls"), "@IsTest private class GladeJsonPrettyEdges67 {\nprivate static void finish(List<Object> rows,Integer expected){System.assertEquals(expected,rows.size(),'Every edge operation retained');String text=JSON.serialize(rows);System.assert(text.length()<2900,'Edge observation exceeds bound');verifyExactEdges(rows);}\nprivate static Map<String,Object> phase(String scenario,String operation,String phaseName){return new Map<String,Object>{'scenario'=>scenario,'operation'=>operation,'phase'=>phaseName};}\nprivate static void error(Map<String,Object> row,Exception e){row.put('type',e.getTypeName());row.put('message',e.getMessage());}\nprivate static void one(List<Object> rows,String scenario,Boolean closeFirst,Integer stopAfter){\nString operation=closeFirst?'close':'getAsString';\nJSONGenerator gen=JSON.createGenerator(true);\nMap<String,Object> row=phase(scenario,operation,'build');\ntry{\nif(scenario=='object'){gen.writeStartObject();}\nelse if(scenario=='array'){gen.writeStartArray();gen.writeNumber(7);}\nelse if(scenario=='nested'){gen.writeStartObject();gen.writeFieldName('items');gen.writeStartArray();gen.writeStartObject();gen.writeStringField('name','owned');}\nelse if(scenario=='pending-field'){gen.writeStartObject();gen.writeFieldName('unfinished');}\nrow.put('returned',true);\n}catch(Exception e){error(row,e);}rows.add(row);if(rows.size()==stopAfter)return;\nrow=phase(scenario,operation,'closedBefore');try{row.put('value',gen.isClosed());}catch(Exception e){error(row,e);}rows.add(row);if(rows.size()==stopAfter)return;\nrow=phase(scenario,operation,'finish');\ntry{if(closeFirst){gen.close();row.put('returned',true);}else{row.put('value',gen.getAsString());}}catch(Exception e){error(row,e);}rows.add(row);if(rows.size()==stopAfter)return;\nrow=phase(scenario,operation,'closedAfter');try{row.put('value',gen.isClosed());}catch(Exception e){error(row,e);}rows.add(row);if(rows.size()==stopAfter)return;\nrow=phase(scenario,operation,'readAfter');try{row.put('value',gen.getAsString());}catch(Exception e){error(row,e);}rows.add(row);if(rows.size()==stopAfter)return;\nrow=phase(scenario,operation,'closedAfterRead');try{row.put('value',gen.isClosed());}catch(Exception e){error(row,e);}rows.add(row);if(rows.size()==stopAfter)return;\n\n}\n@IsTest static void string_object_closedAfterRead(){List<Object> rows=new List<Object>();one(rows,'object',false,6);finish(rows,6);}\n@IsTest static void string_array_closedAfterRead(){List<Object> rows=new List<Object>();one(rows,'array',false,6);finish(rows,6);}\n@IsTest static void string_nested_closedAfterRead(){List<Object> rows=new List<Object>();one(rows,'nested',false,6);finish(rows,6);}\n@IsTest static void string_pending_field_closedAfterRead(){List<Object> rows=new List<Object>();one(rows,'pending-field',false,6);finish(rows,6);}\n@IsTest static void close_object_closedAfterRead(){List<Object> rows=new List<Object>();one(rows,'object',true,6);finish(rows,6);}\n@IsTest static void close_array_closedAfterRead(){List<Object> rows=new List<Object>();one(rows,'array',true,6);finish(rows,6);}\n@IsTest static void close_nested_closedAfterRead(){List<Object> rows=new List<Object>();one(rows,'nested',true,6);finish(rows,6);}\n@IsTest static void close_pending_field_closedAfterRead(){List<Object> rows=new List<Object>();one(rows,'pending-field',true,6);finish(rows,6);}\n\nprivate static void verifyExactEdges(List<Object> rows){\nSystem.assert(rows.size()>0,'Expected at least one observed row');\nMap<String,Object> first=(Map<String,Object>)rows[0];\nString expectedJSON;\nif((String)first.get('scenario') == 'array' && (String)first.get('operation') == 'close')expectedJSON='[{\"returned\":true,\"phase\":\"build\",\"operation\":\"close\",\"scenario\":\"array\"},{\"value\":false,\"phase\":\"closedBefore\",\"operation\":\"close\",\"scenario\":\"array\"},{\"returned\":true,\"phase\":\"finish\",\"operation\":\"close\",\"scenario\":\"array\"},{\"value\":true,\"phase\":\"closedAfter\",\"operation\":\"close\",\"scenario\":\"array\"},{\"value\":\"[ 7 ]\",\"phase\":\"readAfter\",\"operation\":\"close\",\"scenario\":\"array\"},{\"value\":true,\"phase\":\"closedAfterRead\",\"operation\":\"close\",\"scenario\":\"array\"}]';\nelse if((String)first.get('scenario') == 'nested' && (String)first.get('operation') == 'close')expectedJSON='[{\"returned\":true,\"phase\":\"build\",\"operation\":\"close\",\"scenario\":\"nested\"},{\"value\":false,\"phase\":\"closedBefore\",\"operation\":\"close\",\"scenario\":\"nested\"},{\"returned\":true,\"phase\":\"finish\",\"operation\":\"close\",\"scenario\":\"nested\"},{\"value\":true,\"phase\":\"closedAfter\",\"operation\":\"close\",\"scenario\":\"nested\"},{\"value\":\"{\\\\n  \\\\\"items\\\\\" : [ {\\\\n    \\\\\"name\\\\\" : \\\\\"owned\\\\\"\\\\n  } ]\\\\n}\",\"phase\":\"readAfter\",\"operation\":\"close\",\"scenario\":\"nested\"},{\"value\":true,\"phase\":\"closedAfterRead\",\"operation\":\"close\",\"scenario\":\"nested\"}]';\nelse if((String)first.get('scenario') == 'object' && (String)first.get('operation') == 'close')expectedJSON='[{\"returned\":true,\"phase\":\"build\",\"operation\":\"close\",\"scenario\":\"object\"},{\"value\":false,\"phase\":\"closedBefore\",\"operation\":\"close\",\"scenario\":\"object\"},{\"returned\":true,\"phase\":\"finish\",\"operation\":\"close\",\"scenario\":\"object\"},{\"value\":true,\"phase\":\"closedAfter\",\"operation\":\"close\",\"scenario\":\"object\"},{\"value\":\"{ }\",\"phase\":\"readAfter\",\"operation\":\"close\",\"scenario\":\"object\"},{\"value\":true,\"phase\":\"closedAfterRead\",\"operation\":\"close\",\"scenario\":\"object\"}]';\nelse if((String)first.get('scenario') == 'pending-field' && (String)first.get('operation') == 'close')expectedJSON='[{\"returned\":true,\"phase\":\"build\",\"operation\":\"close\",\"scenario\":\"pending-field\"},{\"value\":false,\"phase\":\"closedBefore\",\"operation\":\"close\",\"scenario\":\"pending-field\"},{\"returned\":true,\"phase\":\"finish\",\"operation\":\"close\",\"scenario\":\"pending-field\"},{\"value\":true,\"phase\":\"closedAfter\",\"operation\":\"close\",\"scenario\":\"pending-field\"},{\"value\":\"{\\\\n  \\\\\"unfinished\\\\\" }\",\"phase\":\"readAfter\",\"operation\":\"close\",\"scenario\":\"pending-field\"},{\"value\":true,\"phase\":\"closedAfterRead\",\"operation\":\"close\",\"scenario\":\"pending-field\"}]';\nelse if((String)first.get('scenario') == 'array' && (String)first.get('operation') == 'getAsString')expectedJSON='[{\"returned\":true,\"phase\":\"build\",\"operation\":\"getAsString\",\"scenario\":\"array\"},{\"value\":false,\"phase\":\"closedBefore\",\"operation\":\"getAsString\",\"scenario\":\"array\"},{\"value\":\"[ 7 ]\",\"phase\":\"finish\",\"operation\":\"getAsString\",\"scenario\":\"array\"},{\"value\":true,\"phase\":\"closedAfter\",\"operation\":\"getAsString\",\"scenario\":\"array\"},{\"value\":\"[ 7 ]\",\"phase\":\"readAfter\",\"operation\":\"getAsString\",\"scenario\":\"array\"},{\"value\":true,\"phase\":\"closedAfterRead\",\"operation\":\"getAsString\",\"scenario\":\"array\"}]';\nelse if((String)first.get('scenario') == 'nested' && (String)first.get('operation') == 'getAsString')expectedJSON='[{\"returned\":true,\"phase\":\"build\",\"operation\":\"getAsString\",\"scenario\":\"nested\"},{\"value\":false,\"phase\":\"closedBefore\",\"operation\":\"getAsString\",\"scenario\":\"nested\"},{\"value\":\"{\\\\n  \\\\\"items\\\\\" : [ {\\\\n    \\\\\"name\\\\\" : \\\\\"owned\\\\\"\\\\n  } ]\\\\n}\",\"phase\":\"finish\",\"operation\":\"getAsString\",\"scenario\":\"nested\"},{\"value\":true,\"phase\":\"closedAfter\",\"operation\":\"getAsString\",\"scenario\":\"nested\"},{\"value\":\"{\\\\n  \\\\\"items\\\\\" : [ {\\\\n    \\\\\"name\\\\\" : \\\\\"owned\\\\\"\\\\n  } ]\\\\n}\",\"phase\":\"readAfter\",\"operation\":\"getAsString\",\"scenario\":\"nested\"},{\"value\":true,\"phase\":\"closedAfterRead\",\"operation\":\"getAsString\",\"scenario\":\"nested\"}]';\nelse if((String)first.get('scenario') == 'object' && (String)first.get('operation') == 'getAsString')expectedJSON='[{\"returned\":true,\"phase\":\"build\",\"operation\":\"getAsString\",\"scenario\":\"object\"},{\"value\":false,\"phase\":\"closedBefore\",\"operation\":\"getAsString\",\"scenario\":\"object\"},{\"value\":\"{ }\",\"phase\":\"finish\",\"operation\":\"getAsString\",\"scenario\":\"object\"},{\"value\":true,\"phase\":\"closedAfter\",\"operation\":\"getAsString\",\"scenario\":\"object\"},{\"value\":\"{ }\",\"phase\":\"readAfter\",\"operation\":\"getAsString\",\"scenario\":\"object\"},{\"value\":true,\"phase\":\"closedAfterRead\",\"operation\":\"getAsString\",\"scenario\":\"object\"}]';\nelse if((String)first.get('scenario') == 'pending-field' && (String)first.get('operation') == 'getAsString')expectedJSON='[{\"returned\":true,\"phase\":\"build\",\"operation\":\"getAsString\",\"scenario\":\"pending-field\"},{\"value\":false,\"phase\":\"closedBefore\",\"operation\":\"getAsString\",\"scenario\":\"pending-field\"},{\"value\":\"{\\\\n  \\\\\"unfinished\\\\\" }\",\"phase\":\"finish\",\"operation\":\"getAsString\",\"scenario\":\"pending-field\"},{\"value\":true,\"phase\":\"closedAfter\",\"operation\":\"getAsString\",\"scenario\":\"pending-field\"},{\"value\":\"{\\\\n  \\\\\"unfinished\\\\\" }\",\"phase\":\"readAfter\",\"operation\":\"getAsString\",\"scenario\":\"pending-field\"},{\"value\":true,\"phase\":\"closedAfterRead\",\"operation\":\"getAsString\",\"scenario\":\"pending-field\"}]';\nelse {System.assert(false,'Unknown edge input/operation');return;}\ncompareExactEdgeValue(JSON.deserializeUntyped(expectedJSON),JSON.deserializeUntyped(JSON.serialize(rows)),'rows');\n}\nprivate static void compareExactEdgeValue(Object expected,Object actual,String path){\nif(expected instanceof Map<String,Object>){\n System.assert(actual instanceof Map<String,Object>,'Expected map '+path);\n Map<String,Object> want=(Map<String,Object>)expected;Map<String,Object> got=(Map<String,Object>)actual;\n System.assertEquals(want.keySet(),got.keySet(),'Complete keys '+path);\n for(String key:want.keySet())compareExactEdgeValue(want.get(key),got.get(key),path+'.'+key);\n}else if(expected instanceof List<Object>){\n System.assert(actual instanceof List<Object>,'Expected list '+path);\n List<Object> want=(List<Object>)expected;List<Object> got=(List<Object>)actual;\n System.assertEquals(want.size(),got.size(),'Complete phase population '+path);\n for(Integer i=0;i<want.size();i++)compareExactEdgeValue(want[i],got[i],path+'['+i+']');\n}else System.assertEquals(expected,actual,'Exact value '+path);\n}\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeJsonPrettyEdges67.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\"sourceApiVersion\": \"67.0\", \"packageDirectories\": [{\"path\": \"force-app\", \"default\": true}]}")
	run := Run(loadTestIndex(t, root), Options{})
	if got := run.Summary(); got.Total != 8 || got.Passed != 8 || got.Failed != 0 || got.Skipped != 0 || got.Errors != 0 {
		data, _ := json.Marshal(run)
		t.Fatalf("exact source contracts failed: %s", data)
	}
}
